.step-indicator {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    margin-bottom: 2rem;
    flex-wrap: wrap;
}

.step {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border: 1px solid #ddd;
    border-radius: 2rem;
    background: #f9f9f9;
    cursor: pointer;
    font-size: 0.875rem;
    transition: all 0.2s;
}

.step:disabled {
    cursor: not-allowed;
    opacity: 0.5;
}

.step--current {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
    font-weight: 600;
}

.step--completed {
    background: #198754;
    color: white;
    border-color: #198754;
}

.step--completed:hover {
    background: #157347;
}

.step__badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 50%;
    background: rgba(255,255,255,0.2);
    font-size: 0.75rem;
    font-weight: 700;
}

.step__check {
    font-size: 0.85rem;
}

