namespace sv_33690400bdec4ca8a508937b9997160b.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@namespace sv_33690400bdec4ca8a508937b9997160b.Components.Pages.Apply
@using sv_33690400bdec4ca8a508937b9997160b.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              ValidateEmail="ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep FullName="@personalFullName"
                        Email="@personalEmail"
                        Phone="@personalPhone"
                        Address="@personalAddress"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        IsSubmitting="@isSubmitting"
                        IsSubmitted="@isSubmitted"
                        ApplicationId="@applicationId"
                        ErrorMessage="@submitError"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep;
    private int highestCompletedStep = -1;

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new();

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new();

    // Step 4 state
    private string coverLetter = "";

    // Submission state
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        if (step <= highestCompletedStep + 1)
            currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void AdvanceStep()
    {
        if (currentStep > highestCompletedStep)
            highestCompletedStep = currentStep;
        currentStep++;
    }

    private Task<bool> ValidateEmailAsync(string email)
    {
        return ApplicationService.ValidateEmailAsync(email);
    }

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        AdvanceStep();
    }

    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        AdvanceStep();
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        AdvanceStep();
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        AdvanceStep();
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var workHistory = new WorkHistory(
                workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.EndDate, e.Description
                )).ToList()
            );

            var refList = references.Select(r => new Reference(
                r.Name, r.Relationship, r.Email, r.Phone
            )).ToList();

            var personal = new PersonalInfo(personalFullName, personalEmail, personalPhone, personalAddress);
            var application = new JobApplication(personal, workHistory, refList, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.apply-page {
    max-width: 48rem;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 1.5rem;
    color: #212529;
}

